window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dbb72baa24a0a188"]={"versions": [{"id": "FIG-dbb72baa24a0a188", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm des AUTOSAR-Metamodells (M2-Ebene), Paket <code>DOC_CompositionAggregations</code>.\n</li><li><strong>Funktionaler Kontext:</strong> Spezifiziert die strukturellen Aggregationsbeziehungen und Variabilitätsregeln für Software-Komponenten (<code>SwComponentType</code>) und Kompositionen (<code>CompositionSwComponentType</code>) auf Ebene des Virtual Functional Bus (VFB). Es definiert, wie hierarchische SWC-Strukturen, Ports, Konnektoren und Sub-Komponenten-Instanziierungen im Metamodell aggregiert werden und bis zu welchem Zeitpunkt (Binding Time) Variantenbindungen zulässig sind.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>SwComponentType</code></strong> <em>(Metaklasse, <code>«ARElement»</code>, <code>«AtpType»</code>)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller AUTOSAR-Softwarekomponenten.\n</li><li>Aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>+port</code> (<code>0..*</code>): Referenziert <code>PortPrototype</code> (<code>«AtpPrototype»</code>). Stereotyp <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PreCompileTime</code>.\n</li><li><code>+portGroup</code> (<code>0..*</code>): Referenziert <code>PortGroup</code> (<code>«AtpStructureElement»</code>, <code>«Identifiable»</code>). Stereotyp <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PreCompileTime</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>CompositionSwComponentType</code></strong> <em>(Metaklasse, erbt von <code>SwComponentType</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt eine hierarchische Struktur aus interagierenden Software-Komponenten.\n</li><li>Aggregiert per Komposition (<code>+composition</code>):\n<ul class=\"fig-list\"><li><code>+connector</code> (<code>*</code>): Referenziert <code>SwConnector</code> (<code>«AtpStructureElement»</code>). Stereotypen <code>«atpVariation, atpSplitable»</code> mit Tag <code>Vh.latestBindingTime = PostBuild</code>.\n</li><li><code>+component</code> (<code>1..*</code>): Referenziert <code>SwComponentPrototype</code> (<code>«AtpPrototype»</code>). Stereotypen <code>«atpVariation, atpSplitable»</code> mit Tag <code>Vh.latestBindingTime = PostBuild</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Metamodell-Stereotypen &amp; Tags:</strong>\n<ul class=\"fig-list\"><li><code>«atpVariation»</code>: Kennzeichnet strukturelle Variationspunkte (Variation Points) im Metamodell.\n</li><li><code>«atpSplitable»</code>: Erlaubt das Splitten/Verteilen von Beschreibungsfragmenten über mehrere AUTOSAR-XML-Dateien (ARXML-Dateiaufteilung).\n</li><li><code>Vh.latestBindingTime</code>:\n<ul class=\"fig-list\"><li><code>PreCompileTime</code>: Ports und PortGroups müssen spätestens vor der Kompilierung aufgelöst sein.\n</li><li><code>PostBuild</code>: Die Instanziierung von Sub-Komponenten (<code>SwComponentPrototype</code>) und deren Verbindung (<code>SwConnector</code>) innerhalb einer Komposition kann bis zur Post-Build-Phase variabel gehalten werden.\n</li></ul>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell-Strukturdiagramm):</strong> Es werden keine Laufzeitsequenzen, Task-Aktivierungen oder Callbacks dargestellt.\n</li><li><strong>Metamodell-Semantik:</strong> Die Deklaration eines <code>CompositionSwComponentType</code> erzwingt mindestens einen enthaltenen Prototypen (<code>1..*</code>), während Konnektoren optional sind (<code>0..*</code> / <code>*</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Tooling:</strong>\n<ul class=\"fig-list\"><li>Das Stereotyp <code>«atpSplitable»</code> für <code>+connector</code> und <code>+component</code> erlaubt es Entwicklungsteams, Konnektoren und Komponenteneinbindungen getrennt in modularen ARXML-Dateien zu definieren und zusammenzuführen (Merge-Mechanismus im Tooling).\n</li><li>Ports und PortGroups an <code>SwComponentType</code> sind <em>nicht</em> splittbar; sie müssen konsistent am jeweiligen Komponenten-Typ gehalten werden.\n</li></ul>\n</li><li><strong>Varianten-Management &amp; Binding Time Constraints:</strong>\n<ul class=\"fig-list\"><li><strong>Typ-Ebene (Port/PortGroup):</strong> Varianten (z. B. Vorhandensein bestimmter Schnittstellen über System Constants / SwSystemconst) dürfen spätestens zur Generierungs-/Pre-Compile-Zeit gebunden werden. Eine dynamische Aktivierung zur Laufzeit/Post-Build auf Interface-Ebene ist unzulässig.\n</li><li><strong>Kompositions-Ebene (Prototype/Connector):</strong> Ermöglicht Post-Build-Variabilität (z. B. PB-S / PB-L). Sub-Komponenten und interne Verbindungen (Assembly-/Delegation-Connectors) können nach der Kompilierung über Konfigurationsdatensätze aktiviert oder umkonfiguriert werden, sofern der Codegenerator und die RTE-Implementierung Post-Build-RTE-Konfigurationen unterstützen.\n</li></ul>\n</li><li><strong>RTE-Generierung &amp; Applikationsimplikation:</strong>\n<ul class=\"fig-list\"><li>Mindestens ein <code>SwComponentPrototype</code> muss pro Komposition vorhanden sein; eine leere Komposition ist syntaktisch/metamodell-ungültig.\n</li></ul>\n</li></ul>"}, {"id": "FIG-00dc5541a8a968d8", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm des AUTOSAR-Metamodells (M2-Ebene), Paket <code>DOC_CompositionAggregations</code>.\n</li><li><strong>Funktionaler Kontext:</strong> Spezifiziert die strukturellen Aggregationsbeziehungen und Variabilitätsregeln für Software-Komponenten (<code>SwComponentType</code>) und Kompositionen (<code>CompositionSwComponentType</code>) auf Ebene des Virtual Functional Bus (VFB). Es definiert, wie hierarchische SWC-Strukturen, Ports, Konnektoren und Sub-Komponenten-Instanziierungen im Metamodell aggregiert werden und bis zu welchem Zeitpunkt (Binding Time) Variantenbindungen zulässig sind.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>SwComponentType</code></strong> <em>(Metaklasse, <code>«ARElement»</code>, <code>«AtpType»</code>)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller AUTOSAR-Softwarekomponenten.\n</li><li>Aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>+port</code> (<code>0..*</code>): Referenziert <code>PortPrototype</code> (<code>«AtpPrototype»</code>). Stereotyp <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PreCompileTime</code>.\n</li><li><code>+portGroup</code> (<code>0..*</code>): Referenziert <code>PortGroup</code> (<code>«AtpStructureElement»</code>, <code>«Identifiable»</code>). Stereotyp <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PreCompileTime</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>CompositionSwComponentType</code></strong> <em>(Metaklasse, erbt von <code>SwComponentType</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt eine hierarchische Struktur aus interagierenden Software-Komponenten.\n</li><li>Aggregiert per Komposition (<code>+composition</code>):\n<ul class=\"fig-list\"><li><code>+connector</code> (<code>*</code>): Referenziert <code>SwConnector</code> (<code>«AtpStructureElement»</code>). Stereotypen <code>«atpVariation, atpSplitable»</code> mit Tag <code>Vh.latestBindingTime = PostBuild</code>.\n</li><li><code>+component</code> (<code>1..*</code>): Referenziert <code>SwComponentPrototype</code> (<code>«AtpPrototype»</code>). Stereotypen <code>«atpVariation, atpSplitable»</code> mit Tag <code>Vh.latestBindingTime = PostBuild</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Metamodell-Stereotypen &amp; Tags:</strong>\n<ul class=\"fig-list\"><li><code>«atpVariation»</code>: Kennzeichnet strukturelle Variationspunkte (Variation Points) im Metamodell.\n</li><li><code>«atpSplitable»</code>: Erlaubt das Splitten/Verteilen von Beschreibungsfragmenten über mehrere AUTOSAR-XML-Dateien (ARXML-Dateiaufteilung).\n</li><li><code>Vh.latestBindingTime</code>:\n<ul class=\"fig-list\"><li><code>PreCompileTime</code>: Ports und PortGroups müssen spätestens vor der Kompilierung aufgelöst sein.\n</li><li><code>PostBuild</code>: Die Instanziierung von Sub-Komponenten (<code>SwComponentPrototype</code>) und deren Verbindung (<code>SwConnector</code>) innerhalb einer Komposition kann bis zur Post-Build-Phase variabel gehalten werden.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell-Strukturdiagramm):</strong> Es werden keine Laufzeitsequenzen, Task-Aktivierungen oder Callbacks dargestellt.\n</li><li><strong>Metamodell-Semantik:</strong> Die Deklaration eines <code>CompositionSwComponentType</code> erzwingt mindestens einen enthaltenen Prototypen (<code>1..*</code>), während Konnektoren optional sind (<code>0..*</code> / <code>*</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Tooling:</strong>\n<ul class=\"fig-list\"><li>Das Stereotyp <code>«atpSplitable»</code> für <code>+connector</code> und <code>+component</code> erlaubt es Entwicklungsteams, Konnektoren und Komponenteneinbindungen getrennt in modularen ARXML-Dateien zu definieren und zusammenzuführen (Merge-Mechanismus im Tooling).\n</li><li>Ports und PortGroups an <code>SwComponentType</code> sind <em>nicht</em> splittbar; sie müssen konsistent am jeweiligen Komponenten-Typ gehalten werden.\n</li></ul>\n</li><li><strong>Varianten-Management &amp; Binding Time Constraints:</strong>\n<ul class=\"fig-list\"><li><strong>Typ-Ebene (Port/PortGroup):</strong> Varianten (z. B. Vorhandensein bestimmter Schnittstellen über System Constants / SwSystemconst) dürfen spätestens zur Generierungs-/Pre-Compile-Zeit gebunden werden. Eine dynamische Aktivierung zur Laufzeit/Post-Build auf Interface-Ebene ist unzulässig.\n</li><li><strong>Kompositions-Ebene (Prototype/Connector):</strong> Ermöglicht Post-Build-Variabilität (z. B. PB-S / PB-L). Sub-Komponenten und interne Verbindungen (Assembly-/Delegation-Connectors) können nach der Kompilierung über Konfigurationsdatensätze aktiviert oder umkonfiguriert werden, sofern der Codegenerator und die RTE-Implementierung Post-Build-RTE-Konfigurationen unterstützen.\n</li></ul>\n</li><li><strong>RTE-Generierung &amp; Applikationsimplikation:</strong>\n<ul class=\"fig-list\"><li>Mindestens ein <code>SwComponentPrototype</code> muss pro Komposition vorhanden sein; eine leere Komposition ist syntaktisch/metamodell-ungültig.\n</li></ul>\n</li></ul>"}, {"id": "FIG-5367e6fa7bed4e1e", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm des AUTOSAR-Metamodells (M2-Ebene), Paket <code>DOC_CompositionAggregations</code>.\n</li><li><strong>Funktionaler Kontext:</strong> Spezifiziert die strukturellen Aggregationsbeziehungen und Variabilitätsregeln für Software-Komponenten (<code>SwComponentType</code>) und Kompositionen (<code>CompositionSwComponentType</code>) auf Ebene des Virtual Functional Bus (VFB). Es definiert, wie hierarchische SWC-Strukturen, Ports, Konnektoren und Sub-Komponenten-Instanziierungen im Metamodell aggregiert werden und bis zu welchem Zeitpunkt (Binding Time) Variantenbindungen zulässig sind.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>SwComponentType</code></strong> <em>(Metaklasse, <code>«ARElement»</code>, <code>«AtpType»</code>)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller AUTOSAR-Softwarekomponenten.\n</li><li>Aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>+port</code> (<code>0..*</code>): Referenziert <code>PortPrototype</code> (<code>«AtpPrototype»</code>). Stereotyp <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PreCompileTime</code>.\n</li><li><code>+portGroup</code> (<code>0..*</code>): Referenziert <code>PortGroup</code> (<code>«AtpStructureElement»</code>, <code>«Identifiable»</code>). Stereotyp <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PreCompileTime</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>CompositionSwComponentType</code></strong> <em>(Metaklasse, erbt von <code>SwComponentType</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt eine hierarchische Struktur aus interagierenden Software-Komponenten.\n</li><li>Aggregiert per Komposition (<code>+composition</code>):\n<ul class=\"fig-list\"><li><code>+connector</code> (<code>*</code>): Referenziert <code>SwConnector</code> (<code>«AtpStructureElement»</code>). Stereotypen <code>«atpVariation, atpSplitable»</code> mit Tag <code>Vh.latestBindingTime = PostBuild</code>.\n</li><li><code>+component</code> (<code>1..*</code>): Referenziert <code>SwComponentPrototype</code> (<code>«AtpPrototype»</code>). Stereotypen <code>«atpVariation, atpSplitable»</code> mit Tag <code>Vh.latestBindingTime = PostBuild</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Metamodell-Stereotypen &amp; Tags:</strong>\n<ul class=\"fig-list\"><li><code>«atpVariation»</code>: Kennzeichnet strukturelle Variationspunkte (Variation Points) im Metamodell.\n</li><li><code>«atpSplitable»</code>: Erlaubt das Splitten/Verteilen von Beschreibungsfragmenten über mehrere AUTOSAR-XML-Dateien (ARXML-Dateiaufteilung).\n</li><li><code>Vh.latestBindingTime</code>:\n<ul class=\"fig-list\"><li><code>PreCompileTime</code>: Ports und PortGroups müssen spätestens vor der Kompilierung aufgelöst sein.\n</li><li><code>PostBuild</code>: Die Instanziierung von Sub-Komponenten (<code>SwComponentPrototype</code>) und deren Verbindung (<code>SwConnector</code>) innerhalb einer Komposition kann bis zur Post-Build-Phase variabel gehalten werden.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell-Strukturdiagramm):</strong> Es werden keine Laufzeitsequenzen, Task-Aktivierungen oder Callbacks dargestellt.\n</li><li><strong>Metamodell-Semantik:</strong> Die Deklaration eines <code>CompositionSwComponentType</code> erzwingt mindestens einen enthaltenen Prototypen (<code>1..*</code>), während Konnektoren optional sind (<code>0..*</code> / <code>*</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Tooling:</strong>\n<ul class=\"fig-list\"><li>Das Stereotyp <code>«atpSplitable»</code> für <code>+connector</code> und <code>+component</code> erlaubt es Entwicklungsteams, Konnektoren und Komponenteneinbindungen getrennt in modularen ARXML-Dateien zu definieren und zusammenzuführen (Merge-Mechanismus im Tooling).\n</li><li>Ports und PortGroups an <code>SwComponentType</code> sind <em>nicht</em> splittbar; sie müssen konsistent am jeweiligen Komponenten-Typ gehalten werden.\n</li></ul>\n</li><li><strong>Varianten-Management &amp; Binding Time Constraints:</strong>\n<ul class=\"fig-list\"><li><strong>Typ-Ebene (Port/PortGroup):</strong> Varianten (z. B. Vorhandensein bestimmter Schnittstellen über System Constants / SwSystemconst) dürfen spätestens zur Generierungs-/Pre-Compile-Zeit gebunden werden. Eine dynamische Aktivierung zur Laufzeit/Post-Build auf Interface-Ebene ist unzulässig.\n</li><li><strong>Kompositions-Ebene (Prototype/Connector):</strong> Ermöglicht Post-Build-Variabilität (z. B. PB-S / PB-L). Sub-Komponenten und interne Verbindungen (Assembly-/Delegation-Connectors) können nach der Kompilierung über Konfigurationsdatensätze aktiviert oder umkonfiguriert werden, sofern der Codegenerator und die RTE-Implementierung Post-Build-RTE-Konfigurationen unterstützen.\n</li></ul>\n</li><li><strong>RTE-Generierung &amp; Applikationsimplikation:</strong>\n<ul class=\"fig-list\"><li>Mindestens ein <code>SwComponentPrototype</code> muss pro Komposition vorhanden sein; eine leere Komposition ist syntaktisch/metamodell-ungültig.\n</li></ul>\n</li></ul>"}, {"id": "FIG-864e91e8f6528722", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm des AUTOSAR-Metamodells (M2-Ebene), Paket <code>DOC_CompositionAggregations</code>.\n</li><li><strong>Funktionaler Kontext:</strong> Spezifiziert die strukturellen Aggregationsbeziehungen und Variabilitätsregeln für Software-Komponenten (<code>SwComponentType</code>) und Kompositionen (<code>CompositionSwComponentType</code>) auf Ebene des Virtual Functional Bus (VFB). Es definiert, wie hierarchische SWC-Strukturen, Ports, Konnektoren und Sub-Komponenten-Instanziierungen im Metamodell aggregiert werden und bis zu welchem Zeitpunkt (Binding Time) Variantenbindungen zulässig sind.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>SwComponentType</code></strong> <em>(Metaklasse, <code>«ARElement»</code>, <code>«AtpType»</code>)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller AUTOSAR-Softwarekomponenten.\n</li><li>Aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>+port</code> (<code>0..*</code>): Referenziert <code>PortPrototype</code> (<code>«AtpPrototype»</code>). Stereotyp <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PreCompileTime</code>.\n</li><li><code>+portGroup</code> (<code>0..*</code>): Referenziert <code>PortGroup</code> (<code>«AtpStructureElement»</code>, <code>«Identifiable»</code>). Stereotyp <code>«atpVariation»</code> mit Tag <code>Vh.latestBindingTime = PreCompileTime</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>CompositionSwComponentType</code></strong> <em>(Metaklasse, erbt von <code>SwComponentType</code>)</em>:\n<ul class=\"fig-list\"><li>Kapselt eine hierarchische Struktur aus interagierenden Software-Komponenten.\n</li><li>Aggregiert per Komposition (<code>+composition</code>):\n<ul class=\"fig-list\"><li><code>+connector</code> (<code>*</code>): Referenziert <code>SwConnector</code> (<code>«AtpStructureElement»</code>). Stereotypen <code>«atpVariation, atpSplitable»</code> mit Tag <code>Vh.latestBindingTime = PostBuild</code>.\n</li><li><code>+component</code> (<code>1..*</code>): Referenziert <code>SwComponentPrototype</code> (<code>«AtpPrototype»</code>). Stereotypen <code>«atpVariation, atpSplitable»</code> mit Tag <code>Vh.latestBindingTime = PostBuild</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Metamodell-Stereotypen &amp; Tags:</strong>\n<ul class=\"fig-list\"><li><code>«atpVariation»</code>: Kennzeichnet strukturelle Variationspunkte (Variation Points) im Metamodell.\n</li><li><code>«atpSplitable»</code>: Erlaubt das Splitten/Verteilen von Beschreibungsfragmenten über mehrere AUTOSAR-XML-Dateien (ARXML-Dateiaufteilung).\n</li><li><code>Vh.latestBindingTime</code>:\n<ul class=\"fig-list\"><li><code>PreCompileTime</code>: Ports und PortGroups müssen spätestens vor der Kompilierung aufgelöst sein.\n</li><li><code>PostBuild</code>: Die Instanziierung von Sub-Komponenten (<code>SwComponentPrototype</code>) und deren Verbindung (<code>SwConnector</code>) innerhalb einer Komposition kann bis zur Post-Build-Phase variabel gehalten werden.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell-Strukturdiagramm):</strong> Es werden keine Laufzeitsequenzen, Task-Aktivierungen oder Callbacks dargestellt.\n</li><li><strong>Metamodell-Semantik:</strong> Die Deklaration eines <code>CompositionSwComponentType</code> erzwingt mindestens einen enthaltenen Prototypen (<code>1..*</code>), während Konnektoren optional sind (<code>0..*</code> / <code>*</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Tooling:</strong>\n<ul class=\"fig-list\"><li>Das Stereotyp <code>«atpSplitable»</code> für <code>+connector</code> und <code>+component</code> erlaubt es Entwicklungsteams, Konnektoren und Komponenteneinbindungen getrennt in modularen ARXML-Dateien zu definieren und zusammenzuführen (Merge-Mechanismus im Tooling).\n</li><li>Ports und PortGroups an <code>SwComponentType</code> sind <em>nicht</em> splittbar; sie müssen konsistent am jeweiligen Komponenten-Typ gehalten werden.\n</li></ul>\n</li><li><strong>Varianten-Management &amp; Binding Time Constraints:</strong>\n<ul class=\"fig-list\"><li><strong>Typ-Ebene (Port/PortGroup):</strong> Varianten (z. B. Vorhandensein bestimmter Schnittstellen über System Constants / SwSystemconst) dürfen spätestens zur Generierungs-/Pre-Compile-Zeit gebunden werden. Eine dynamische Aktivierung zur Laufzeit/Post-Build auf Interface-Ebene ist unzulässig.\n</li><li><strong>Kompositions-Ebene (Prototype/Connector):</strong> Ermöglicht Post-Build-Variabilität (z. B. PB-S / PB-L). Sub-Komponenten und interne Verbindungen (Assembly-/Delegation-Connectors) können nach der Kompilierung über Konfigurationsdatensätze aktiviert oder umkonfiguriert werden, sofern der Codegenerator und die RTE-Implementierung Post-Build-RTE-Konfigurationen unterstützen.\n</li></ul>\n</li><li><strong>RTE-Generierung &amp; Applikationsimplikation:</strong>\n<ul class=\"fig-list\"><li>Mindestens ein <code>SwComponentPrototype</code> muss pro Komposition vorhanden sein; eine leere Komposition ist syntaktisch/metamodell-ungültig.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-dbb72baa24a0a188", "to": "FIG-00dc5541a8a968d8", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-00dc5541a8a968d8", "to": "FIG-5367e6fa7bed4e1e", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5367e6fa7bed4e1e", "to": "FIG-864e91e8f6528722", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
